data.command:
$ErrorActionPreference='Stop'
Start-Sleep -Seconds 3
$src = Join-Path $env:USERPROFILE 'HeavenBridgeSource'
if (-not (Test-Path (Join-Path $src '.git'))) {
  & git clone --branch main --single-branch https://github.com/fengie/mhw-mods.git $src
  if ($LASTEXITCODE -ne 0) { throw "clone failed: $LASTEXITCODE" }
}
& git -C $src fetch origin main
if ($LASTEXITCODE -ne 0) { throw "fetch failed: $LASTEXITCODE" }
& git -C $src checkout -B main origin/main
if ($LASTEXITCODE -ne 0) { throw "checkout failed: $LASTEXITCODE" }
& git -C $src reset --hard origin/main
if ($LASTEXITCODE -ne 0) { throw "reset failed: $LASTEXITCODE" }
& git -C $src clean -fd -- heaven-bridge
if ($LASTEXITCODE -ne 0) { throw "clean failed: $LASTEXITCODE" }
$head = (& git -C $src rev-parse HEAD).Trim()
Write-Output "INSTALL_SOURCE=$head"
& (Join-Path $src 'heaven-bridge\bootstrap.ps1')
if (-not $?) { throw 'bootstrap failed' }
Start-Sleep -Seconds 5
& (Join-Path $src 'heaven-bridge\manage.ps1') STATUS
